    for c in range(W):
        idx=[r for r in range(H) if g[r][c]==mi]
        for a,b in zip(idx,idx[1:]):
            L=b-a-1
            pA=sum(1 for dc in range(-2,3) if 0<=c+dc<W and g[a][c+dc]!=g[a][c] and g[a][c+dc]!=mi)
            pB=sum(1 for dc in range(-2,3) if 0<=c+dc<W and g[b][c+dc]!=g[b][c] and g[b][c+dc]!=mi)
