G=load()
# Check connectivity: for each demo's background, check whether bg is one component; and check if the changed cells form multiple components of size 1 (noise).
for i in [7]:
    gi=G[f'Demo pair {i} input']
    from collections import deque
    H,W=len(gi),len(gi[0])
    bgv=Counter(x for r in gi for x in r).most_common(1)[0][0]
    vis=[[False]*W for _ in range(H)]; comps=[]
    for r in range(H):
        for c in range(W):
            if gi[r][c]==bgv and not vis[r][c]:
                q=deque([(r,c)]);vis[r][c]=True;comp=[]
                while q:
                    x,y=q.popleft();comp.append((x,y))
                    for dy,dx in ((0,1),(0,-1),(1,0),(-1,0)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<H and 0<=ny<W and not vis[nx][ny] and gi[nx][ny]==bgv:
                            vis[nx][ny]=True;q.append((nx,ny))
                comps.append(comp)
    print('num bg comps:',len(comps),[len(c) for c in comps][:20])
